# ИИ-черновик (D-25): английские существительные, топ-100. pl — множественное число (None — нет).
def N(tr, pl, ex1, ex2, pair=None, note=None):
    d = dict(tr=tr, ex=[ex1, ex2])
    if pl: d['F'] = {'plural': pl}
    if pair: d['pair'] = 'es:' + pair
    if note: d['note'] = note
    return d

